from produire import produire,paras,steps,table
from medicaments_suite import ciprofloxacine
parts=[
('La {kératite infectieuse} est une infection de la cornée. Elle peut être bactérienne, virale, fongique ou parasitaire. Un infiltrat ou un ulcère peut menacer rapidement la transparence et l’intégrité cornéennes.',paras('La cornée constitue la partie transparente antérieure de l’œil. Une infection peut détruire l’épithélium puis le tissu sous-jacent ; un ulcère désigne une perte de substance et ne doit pas être confondu avec une simple rougeur conjonctivale.', 'Le résumé européen sur la kératite microbienne traite les formes bactériennes et fongiques. Les HUG incluent aussi les formes virales et parasitaires ; leur prise en charge étiologique ne se déduit pas d’une ordonnance d’antibiotique antibactérien.')),
('Le {terrain oriente les causes sans remplacer les prélèvements}. Le port de lentilles est un facteur majeur. Traumatisme, chirurgie, exposition et altération de la surface augmentent aussi le risque.',paras('Rechercher port nocturne ou entretien inadéquat des lentilles, contact avec l’eau, lésion cornéenne et traitements locaux. Une immunodépression ou une sécheresse importante peut fragiliser la surface.', 'Les HUG insistent également sur les paralysies faciale et trigéminale, responsables d’exposition ou d’une moindre protection sensitive. Une douleur peu intense ne rassure donc pas complètement si la sensibilité cornéenne est altérée. Aucune fréquence suisse comparative n’est établie ici.')),
('Le {mécanisme associe défaut de barrière et destruction tissulaire}. L’épithélium protège la cornée contre les agents infectieux. L’inflammation et l’infection peuvent produire opacité, amincissement et perforation.',paras('Un traumatisme ou une surface fragile favorise l’entrée des agents infectieux. Un infiltrat blanchâtre peut s’associer à une ulcération visible après coloration ; la lésion peut aussi s’étendre en profondeur.', 'Une localisation centrale menace particulièrement la fonction visuelle. La cicatrice peut persister après contrôle de l’infection. Le contrôle de la douleur ne prouve ni la stérilisation ni la solidité du tissu cornéen.')),
('Le {tri considère la suspicion de kératite comme une urgence}. Appeler l’ophtalmologue sans attendre un essai thérapeutique de plusieurs jours. Une baisse visuelle ou un point blanc cornéen renforce l’alerte.',paras('Un œil rouge douloureux chez un porteur de lentilles doit faire rechercher une atteinte cornéenne. Photophobie marquée, difficulté à ouvrir l’œil, larmoiement et vision floue sont compatibles avec ce diagnostic.', 'Les HUG recommandent une orientation urgente pour toute suspicion. La possibilité britannique de traiter certains petits ulcères dans une filière optométrique formée ne se transpose pas automatiquement à un premier recours dépourvu de matériel et de suivi spécialisé.')),
('L’{anamnèse reconstitue les expositions et la vitesse d’évolution}. Demander lentilles, eau, traumatisme et chirurgie récente. Relever tous les collyres utilisés, en particulier les corticoïdes.',paras('Noter l’heure de début, progression, baisse visuelle, sécrétions et douleur. Un traumatisme végétal, une exposition à l’eau avec lentilles ou des épisodes herpétiques peuvent orienter l’enquête étiologique sans prouver le germe.', 'Demander sécheresse, fermeture palpébrale incomplète, immunodépression et traitements généraux. Conserver les lentilles et leur étui pour l’équipe qui peut souhaiter les analyser ; les retirer sans les réutiliser et ne pas les nettoyer avant les instructions de cette équipe.')),
('L’{examen documente la vision et la lésion cornéenne}. Mesurer l’acuité de chaque œil. La lampe à fente permet d’apprécier infiltrat, ulcération et inflammation associée.',paras('Décrire localisation, dimensions, profondeur, amincissement et atteinte de l’axe visuel pour suivre l’évolution. La fluorescéine met en évidence une perte épithéliale ; une opacité et une coloration doivent être interprétées ensemble.', 'Observer chambre antérieure, pupille et paupières selon les possibilités. Un hypopion ou une suspicion de perforation exige une prise en charge spécialisée immédiate. Éviter pression et manipulations inutiles si l’intégrité du globe est menacée.')),
('L’{approche syndromique distingue infection et autres atteintes de surface}. Une ulcération peut être infectieuse ou non infectieuse. L’antibiothérapie empirique ne doit pas faire oublier une autre cause.',table(['Contexte ou aspect','Question clinique'],[['Infiltrat avec perte épithéliale, lentilles ou sécrétions.','Infection bactérienne possible ; prélèvement et traitement spécialisé selon gravité.'],['Traumatisme végétal ou évolution atypique.','Rechercher notamment une infection fongique.'],['Lentilles et eau, douleur ou évolution inhabituelles.','Discuter une infection amibienne.'],['Antécédents herpétiques ou lésion évocatrice.','Rechercher une kératite herpétique ; le traitement antibactérien seul est insuffisant.'],['Exposition ou trouble sensitif.','Atteinte neurotrophique ou d’exposition, avec ou sans surinfection.'],['Douleur et rougeur sans explication cornéenne.','Rechercher uvéite, sclérite ou fermeture d’angle.']])) ,
('Le {diagnostic positif associe examen cornéen et contexte}. Un ulcère infectieux probable doit être traité sans retard dangereux. L’identification du germe précise ensuite le traitement.',paras('L’ophtalmologue confirme la localisation et juge la nécessité de prélèvements. Un frottis conjonctival ne remplace pas automatiquement le prélèvement de la lésion cornéenne.', 'La couleur des sécrétions ou l’intensité de la douleur n’identifie pas à elle seule l’agent. Une culture négative, surtout après un traitement, n’exclut pas formellement l’infection et doit être interprétée avec l’évolution.')),
('Les {examens microbiologiques sont ciblés et organisés rapidement}. Un prélèvement de l’ulcère peut rechercher bactéries, champignons ou autres agents. Il ne doit pas retarder dangereusement le traitement.',paras('Le spécialiste choisit prélèvement cornéen, examen direct, culture et examens complémentaires selon la gravité et le contexte. Les lentilles et l’étui peuvent aider à identifier une source, sans que leur contamination prouve seule le germe causal de la cornée.', 'Un échec demande de revoir diagnostic, observance, sensibilité du germe et pénétration du traitement. Les examens moléculaires ou d’imagerie spécialisés sont adaptés à l’hypothèse ; aucun panel universel ni seuil diagnostique non sourcé n’est imposé.')),
('L’{algorithme organise prélèvement, traitement et surveillance}. Retirer les lentilles et joindre l’ophtalmologue immédiatement. La fréquence d’administration doit être réalisable.',steps('Mesurer la vision, identifier lentilles, traumatisme, chirurgie et signes de menace cornéenne.', 'Organiser l’examen spécialisé urgent ; conserver lentilles et étui pour les investigations éventuelles.', 'Prélever la lésion si indiqué, avant antimicrobien lorsque cela est possible sans retard dangereux.', 'Commencer le traitement local intensif prescrit selon l’agent probable et la gravité.', 'Vérifier possibilité d’administration nocturne et de contrôle rapproché ; hospitaliser si nécessaire.', 'Adapter au résultat, à la cicatrisation et à la tolérance ; réévaluer sans délai si aggravation.')),
('La {prise en charge suisse est urgente et dépend de l’agent}. Une kératite bactérienne peut nécessiter des instillations très fréquentes. Une forme virale, fongique ou parasitaire exige une stratégie différente.',paras('L’ophtalmologue choisit l’antimicrobien, sa concentration et le rythme selon l’ulcère et les prélèvements. Les formes sévères peuvent nécessiter une hospitalisation pour assurer les traitements de jour et de nuit.', '@@MEDICAMENTS@@', 'Les antifongiques, antiamibiens et antiviraux nécessitent une prescription adaptée ; un antibiotique comme la ciprofloxacine ne les remplace pas. Une préparation renforcée ou magistrale n’est pas assimilée à la spécialité commerciale citée.', 'Ne pas débuter seul un corticoïde sur une kératite infectieuse suspectée. Une éventuelle corticothérapie adjuvante relève d’une décision spécialisée, après évaluation de l’agent et du contrôle infectieux. La suspension Maxidex présentée pour l’uvéite a des contre-indications explicites pour les lésions cornéennes et infections.', 'Une perforation ou une infection incontrôlée peut exiger un geste chirurgical. L’antalgie et, dans certains cas, une cycloplégie sont organisées par l’équipe ; elles ne doivent pas masquer la nécessité d’un contrôle de l’infection.')),
('La {prévention associe entretien des lentilles et suivi de la surface}. Respecter les règles de port et éviter les expositions inadaptées à l’eau. Corriger les facteurs de fragilité cornéenne.',paras('Ne pas reprendre les lentilles avant accord de l’ophtalmologue. Après les prélèvements éventuels, renouveler ou décontaminer le matériel selon ses instructions ; ne pas jeter immédiatement les éléments utiles au diagnostic.', 'Surveiller douleur, vision, aspect de l’ulcère et observance à chaque contrôle. Une amélioration subjective ne suffit pas à interrompre précocement le traitement. Le suivi recherche cicatrice, amincissement et retentissement visuel.')),
('Le {point clé} est de protéger la vision sans retarder l’expertise. Une kératite ne se traite pas comme une conjonctivite banale. Le contrôle rapproché fait partie du traitement.',paras('Les décisions reposent sur localisation, profondeur, agent probable, terrain et réponse. Le schéma chiffré d’un ulcère bactérien sensible reste un exemple réglementaire précis, pas une ordonnance universelle pour toutes les kératites.'))]
quiz=[('Une kératite concerne-t-elle la seule conjonctive ?','Non, elle atteint la cornée.'),('Quel terrain doit alerter devant un œil rouge douloureux ?','Le port de lentilles, entre autres facteurs.'),('L’absence de douleur forte exclut-elle une atteinte grave ?','Non, notamment si la sensibilité cornéenne est altérée.'),('Un point blanc sur la cornée justifie-t-il un essai de plusieurs jours sans examen ?','Non, évaluation urgente.'),('Faut-il jeter immédiatement lentilles et étui ?','Non, ils peuvent être utiles à l’identification de la cause.'),('Que documenter pour le suivi ?','Vision, localisation, dimensions et profondeur de la lésion, puis évolution.'),('Un frottis conjonctival remplace-t-il toujours le prélèvement cornéen ?','Non.'),('La culture négative exclut-elle toute infection ?','Non, elle s’interprète avec le contexte et les traitements antérieurs.'),('Le schéma Ciloxan de l’ulcère inclut-il la nuit ?','Oui, selon la notice suisse citée.'),('Peut-on remplacer ce schéma par celui d’une conjonctivite ?','Non.'),('La ciprofloxacine traite-t-elle une kératite amibienne ou herpétique ?','Non.'),('Un corticoïde peut-il être commencé seul sur une infection cornéenne suspectée ?','Non.'),('Quand l’hospitalisation peut-elle être nécessaire ?','Si la gravité ou l’impossibilité d’assurer les soins et le suivi l’exige.'),('Une douleur qui diminue autorise-t-elle à arrêter le suivi ?','Non, l’état cornéen et la vision doivent être contrôlés.')]
produire(7,parts,quiz,(1,4,19),ciprofloxacine)
